INSERT INTO assessment_results (assessment_id, overall_score, python_score, sql_score, javascript_score, html_score, css_score, strengths, improvement_opportunities, profile_description) VALUES (:d1014363495_id_assessment, 68.57, 57.14, 71.43, 100.00, 57.14, 57.14, 'Demuestra un dominio sólido en JavaScript y SQL, con puntajes que reflejan una comprensión clara de los conceptos fundamentales y una buena capacidad de aplicación práctica en estas áreas.', 'Podría reforzar sus bases en HTML y CSS, dedicando tiempo adicional a la práctica de ejercicios y a la revisión de los conceptos clave de estas tecnologías.', 'El estudiante muestra un desempeño general dentro del promedio esperado (68.57%), con un perfil técnico consistente. Cuenta con una base adecuada para aportar en un equipo de trabajo, con espacio de crecimiento en las áreas de menor puntaje.');

