JOIN answer_options ao ON ao.question_id = q.id_question
WHERE (REPLACE(q.statement, CHR(13), ''), REPLACE(ao.content, CHR(13), '')) IN (
('¿Qué devuelve print(type(5.0))?', '<class ''int''>'),
('¿Qué imprime print([1, 2, 3][1])?', '2'),
('¿Qué imprime print("abc"[::-1])?', 'bac'),
('¿Cuál es la palabra clave para definir una función en Python?', 'func'),
('¿Cuál es el tipo de dato inmutable que se define con paréntesis ()?', 'Tupla'),
('¿Qué devuelve [x for x in range(5) if x % 2 == 0]?', '[0, 2, 4]'),
('¿Qué método se usa para agregar un elemento al final de una lista?', 'add()'),
('¿Qué atributo de <img> especifica la ruta de la imagen?', 'src'),
('¿Qué significa la sigla HTML?', 'HyperText Markup Language'),
('¿Qué tipo de input se usa para capturar una fecha?', 'type="time"'),
('¿Qué elemento agrupa opciones relacionadas dentro de un <select>?', '<fieldset>'),
('¿Qué atributo de <form> especifica hacia dónde se envían los datos?', 'action'),
('¿Qué elemento se usa para insertar contenido de video?', '<video>'),
('¿Qué atributo permite subir múltiples archivos en un input type="file"?', 'multiple'),
('¿Qué propiedad cambia el color del texto?', 'font-color'),
('¿Qué propiedad cambia el color de fondo de un elemento?', 'color'),
('¿Cuál es la diferencia entre class e id como selectores?', 'Son exactamente lo mismo'),
('¿Qué propiedad convierte un contenedor en flexbox?', 'display: flexbox'),
('¿Qué hace position: absolute;?', 'Posiciona el elemento respecto a su ancestro posicionado más cercano'),
('¿Qué es la especificidad en CSS?', 'El tamaño del archivo CSS'),
('¿Qué sintaxis se usa para crear una variable CSS personalizada?', '--variable: valor;'),
('¿Qué imprime console.log(typeof null)?', '"object"'),
('¿Cuál es la diferencia entre let y var respecto a su alcance (scope)?', 'let tiene alcance de bloque, var tiene alcance de función'),
('¿Qué estructura de datos usa {} para almacenar pares clave-valor?', 'Objeto'),
('¿Qué imprime este código?
function contador() {
  let n = 0;
  return () => ++n;
}
const c = contador();
console.log(c(), c());', '1 2'),
('¿Qué devuelve [1, 2, 3].map(x => x * 2)?', '[2, 4, 6]'),
('¿Qué imprime console.log(typeof (function(){}))?', '"function"'),
('¿Qué es una Promise en JavaScript?', 'Un objeto que representa la eventual finalización (o falla) de una operación asíncrona'),
('¿Qué cláusula filtra filas según una condición?', 'HAVING'),
('¿Qué cláusula ordena los resultados de una consulta?', 'ORDER BY'),
('¿Qué operador se usa para buscar un patrón de texto?', 'LIKE'),
('¿Qué es una clave primaria (primary key)?', 'Un tipo de índice obsoleto'),
('¿Qué es una subconsulta (subquery)?', 'Un tipo de JOIN especial'),
('¿Qué significa la propiedad ACID en una transacción?', 'Atomicidad, Consistencia, Aislamiento y Durabilidad'),
('¿Qué cláusula se usa para definir particiones en una función de ventana?', 'ORDER BY')
);
INSERT INTO assessment_results (assessment_id, overall_score, python_score, sql_score, javascript_score, html_score, css_score, strengths, improvement_opportunities, profile_description) VALUES (:d1113055488_id_assessment, 57.14, 42.86, 42.86, 100.00, 71.43, 28.57, 'Demuestra un dominio sólido en JavaScript y HTML, con puntajes que reflejan una comprensión clara de los conceptos fundamentales y una buena capacidad de aplicación práctica en estas áreas.', 'Podría reforzar sus bases en SQL y CSS, dedicando tiempo adicional a la práctica de ejercicios y a la revisión de los conceptos clave de estas tecnologías.', 'El estudiante presenta un desempeño general aún en desarrollo (57.14%). Se recomienda reforzar los fundamentos técnicos antes de asumir tareas de alta complejidad, priorizando la práctica constante en las tecnologías con menor puntaje.');

